import{_ as t,o,c as d,a7 as r}from"./chunks/framework.BJyR0VjM.js";const x=JSON.parse('{"title":"Exit Codes","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/exit-codes.md","filePath":"documentation/exit-codes.md"}'),s={name:"documentation/exit-codes.md"};function a(i,e,n,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="exit-codes" tabindex="-1">Exit Codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to “Exit Codes”">​</a></h1><p>YggUtils uses exit codes to communicate the reason it stopped. This is useful for hosting panels or scripts that monitor the wrapper process.</p><h2 id="yggutils-exit-codes" tabindex="-1">YggUtils Exit Codes <a class="header-anchor" href="#yggutils-exit-codes" aria-label="Permalink to “YggUtils Exit Codes”">​</a></h2><p>These are exit codes produced by the <strong>YggUtils wrapper itself</strong>, not the Minecraft server.</p><table tabindex="0"><thead><tr><th>Code</th><th>Reason</th></tr></thead><tbody><tr><td><code>0</code></td><td>Config file was missing and has been generated — fill it in and re-run</td></tr><tr><td><code>0</code></td><td>Config values are empty — fill in <code>authserver</code> and <code>serverfile</code></td></tr><tr><td><code>0</code></td><td>Server exited cleanly (exit code <code>0</code> from the server process)</td></tr><tr><td><code>1</code></td><td><code>serverfile</code> path does not exist on disk</td></tr><tr><td><code>1</code></td><td>authlib-injector download failed</td></tr><tr><td><code>1</code></td><td>authlib-injector file missing after attempted download</td></tr></tbody></table><h2 id="server-exit-codes" tabindex="-1">Server Exit Codes <a class="header-anchor" href="#server-exit-codes" aria-label="Permalink to “Server Exit Codes”">​</a></h2><p>These are exit codes produced by the <strong>Minecraft server process</strong> itself, which YggUtils observes:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th><th>YggUtils Action</th></tr></thead><tbody><tr><td><code>0</code></td><td>Clean shutdown via <code>/stop</code> or equivalent</td><td>Wrapper exits with code <code>0</code></td></tr><tr><td>Non-zero</td><td>Crash, OOM kill, or unexpected termination</td><td>Restart after 3 seconds</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>YggUtils does not remap or translate server exit codes. The restart decision is based purely on whether the code is <code>0</code> or not.</li><li>If your hosting panel monitors the wrapper process exit code, a <code>0</code> always means either a clean stop or a setup step (config generated/incomplete). A <code>1</code> means something is misconfigured or a download failed.</li></ul>',10)])])}const g=t(s,[["render",a]]);export{x as __pageData,g as default};
